import { expect, test } from '../../fixtures/billing';
import { PERIOD_END, projects } from '../../fixtures/testData';

test('BR-04 printed USD lines add up to the subtotal, each line rounded in the invoice currency before tax @critical', async ({ proposal, page }) => {
  await proposal.create(projects.polarReporting, PERIOD_END);

  // +0.05 EUR on lines 1 and 2 leaves 0.004175 USD after rounding on each, and line 3 (252.00 EUR) leaves 0.002.
  // The rounded lines add up to 2,613.50; rounding only the total would print 2,613.51.
  await proposal.adjust(1, '0.05', 'Rounding check');
  await expect(proposal.line(1).locator('.line-adjustment')).toHaveText('+0.05');
  await proposal.adjust(2, '0.05', 'Rounding check');
  await expect(proposal.line(2).locator('.line-adjustment')).toHaveText('+0.05');

  await expect(page.locator('#proposal-currency')).toHaveText('USD');
  await expect(page.locator('#proposal-rate')).toHaveText('1.0835');
  await expect(proposal.lines).toHaveCount(3);
  await expect(proposal.line(3)).toContainText('2026-10-14');
  await expect(proposal.line(3).locator('.line-quantity')).toHaveText('2.10');
  await expect(proposal.amountOf(1)).toHaveText('1,300.25');
  await expect(proposal.amountOf(2)).toHaveText('1,040.21');
  await expect(proposal.amountOf(3)).toHaveText('273.04');
  await expect(proposal.line(3).locator('.line-tax')).toHaveText('69.63');
  await expect(proposal.subtotal).toHaveText('2,613.50');
  await expect(proposal.tax).toHaveText('666.44');
  await expect(proposal.total).toHaveText('3,279.94 USD');

  page.once('dialog', (dialog) => dialog.accept());
  await page.locator('#delete-proposal').click();
  await page.getByRole('status').waitFor();
});
